from lib import *
S = SS('s20')
steps = [
    step("状态码与请求方法:GET 请求遇到 301、302、303、307、308 都是跳转后继续 GET;POST 请求遇到 301、302、303 变成 GET 并且请求体丢掉(空),遇到 307、308 仍然是 POST 并带着原来的请求体 a=1(源码:301/302 的 POST 与 303 的非 GET/HEAD 请求改用 GET)。", t=tl(S(1)), mark=lidx(S(1), '301     POST', '302     POST', '303     POST'), done=lidx(S(1), '307     POST', '308     POST'), kv=KV([['301 / 302 / 303 的 POST', '改成 GET,丢请求体'], ['307 / 308 的 POST', '保持 POST,带请求体'], ['GET', '一律保持 GET']], ['301 / 302 / 303 的 POST'])),
    step("meta 里的跳转记录:/hop1 → 302 → /hop2 → 301 → …/hop3#frag → 307 → /target。回调拿到的响应:response.url 是最终的 …/target;response.request.url 是 …/target#frag(请求保留了从 301 那一跳带来的片段);meta['redirect_urls'] 依次是 hop1、hop2、hop3#frag(每一跳的来源 URL),redirect_reasons = [302, 301, 307],redirect_times = 3,redirect_ttl = 17(= 20 − 3)。服务器收到的路径是 /hop1 → /hop2 → /hop3 → /target(片段不会发给服务器)。", t=tl(S(2)), mark=lidx(S(2), 'redirect_urls', 'redirect_reasons', 'redirect_times', 'redirect_ttl'), done=lidx(S(2), 'final_url', 'request_url'), kv=KV([['redirect_urls', '每一跳的来源 URL'], ['redirect_reasons', '[302, 301, 307]'], ['redirect_times / ttl', '3 / 17'], ['response.url 与 request.url', 'target 与 target#frag']], ['redirect_urls'])),
    step("循环重定向(每次跳到一个新 URL /l?i=N+1)到 REDIRECT_MAX_TIMES 为止:默认 20 时服务器收到 21 次请求(原请求 + 20 次跳转),下一次跳转被丢弃,errback 拿到 IgnoreRequest: max redirections reached;设成 3,服务器收到 4 次。注意如果循环跳回同一个 URL(如 /loop → /loop),第二次就被去重吃掉了,根本到不了上限。", t=tl(S(3)), mark=lidx(S(3), 'REDIRECT_MAX_TIMES=20', 'REDIRECT_MAX_TIMES=3'), b=bars([['MAX_TIMES=20', 21, '21 次请求'], ['MAX_TIMES=3', 4, '4 次请求']], 21, mark=[0, 1]), kv=KV([['REDIRECT_MAX_TIMES = 20(默认)', '请求 21 次后丢弃'], ['= 3', '请求 4 次后丢弃'], ['丢弃时', 'errback 收到 IgnoreRequest'], ['跳回同一个 URL', '被去重,到不了上限']], ['REDIRECT_MAX_TIMES = 20(默认)'])),
    step("不想自动跳转:meta dont_redirect = True 时 302 响应不会被处理,但 302 不在“可通过”的状态码里,HttpErrorMiddleware 把它拦下,走 errback(HttpError);再加上 handle_httpstatus_list = [302],回调直接拿到 status = 302 的响应,Location 头 = /target,服务器只收到 /r302 和 /r302?b 两个请求(没有 /target)。", t=tl(S(4)), mark=lidx(S(4), 'errback', "'status': 302"), kv=KV([['dont_redirect', '不跳转,但 302 被 HttpError 拦成 errback'], ['handle_httpstatus_list = [302]', '回调拿到 302 响应和 Location'], ['服务器', '没有收到 /target']], ['handle_httpstatus_list = [302]'])),
    step("跳转请求的头(COOKIES_ENABLED = 0 以便看到原始 Cookie 头):跳到另一个主机名 localhost 时 Cookie 和 Authorization 都被删掉,自定义头 X-Custom 保留,Referer 是原请求的 URL;同主机跳转 Cookie 与 Authorization 都保留。另外跳转请求的优先级 +2(REDIRECT_PRIORITY_ADJUST),并发 1 时 /r302?a 的跳转目标 /target 插到 plain1、plain2 前面:顺序 /r302?a → /target → /plain1 → /plain2。", t=tl(S(5)), mark=lidx(S(5), '跳到另一个主机名', '优先级 +2'), done=lidx(S(5), '同主机跳转'), kv=KV([['跨主机', 'Cookie、Authorization 删除'], ['同主机', 'Cookie、Authorization 保留'], ['Referer', '设为原请求 URL'], ['优先级', '+2,重定向插队']], ['跨主机'])),
    step("Location 的写法:相对路径 /target、协议相对 //localhost:端口/target 都能跟随(回调拿到 200,url 为 …/target);302 没有 Location 头,不跳转,回调(配合 handle_httpstatus_list)拿到 status = 302;Location 是 ftp:// 这类非 http(s) 协议,同样不跳转,回调拿到 302。", t=tl(S(6)), mark=lidx(S(6), '没有 Location', 'ftp'), done=lidx(S(6), '相对路径', '协议相对'), kv=KV([['相对路径 / 协议相对', '照常跟随'], ['没有 Location', '不跳转,返回 302'], ['非 http(s) 协议', '不跳转,返回 302']], ['没有 Location'])),
    step("HTML 里的 <meta http-equiv=\"refresh\">(MetaRefreshMiddleware):content 里的秒数 0、5、99 都会跳到 /target(redirect_reasons 记 'meta refresh'),而且不真等——耗时都只有 0.01 s;秒数 100 和 101 不跳转(要求秒数小于 METAREFRESH_MAXDELAY = 100),最终仍停在 meta100 / meta101 页面,redirect_reasons 为 None。", t=tl(S(7)), mark=lidx(S(7), '100; url', '101; url'), done=lidx(S(7), '0; url', '5; url', '99; url'), kv=KV([['0 / 5 / 99 秒', '立即跳转,不等待'], ['100 / 101 秒', '不跳转(须 < METAREFRESH_MAXDELAY)'], ['记录', 'redirect_reasons = ["meta refresh"]']], ['0 / 5 / 99 秒'])),
]
A = mkarts('s20', 20, 'Scrapy,RedirectMiddleware,重定向,meta refresh,redirect_urls,真实验证,动画演示',
    '实测重定向中间件:301/302/303 的 POST 变 GET 丢请求体、307/308 保持 POST;meta 记录 redirect_urls/reasons/times/ttl;REDIRECT_MAX_TIMES = 20 时服务器收到 21 次请求后丢弃(errback 拿到 IgnoreRequest),跳回同一 URL 会被去重;跨主机删除 Cookie/Authorization;meta refresh 秒数 < 100 就立即跳转。',
    '服务器返回 302 以后 Scrapy 会怎么做?POST 还是 POST 吗?跳转几次就放弃?请求头会不会跟着走到别的域名?这篇给每个问题造一个服务器场景,把 RedirectMiddleware 和 MetaRefreshMiddleware 的行为一项项量出来。',
    [('21 次', 'REDIRECT_MAX_TIMES = 20 时无限重定向,服务器收到的请求数(原请求 + 20 次跳转)'), ('POST → GET', '301/302/303 跳转后的方法(307/308 保持 POST)'), ('< 100 秒', 'meta refresh 会被立即跟随的秒数门槛,不会真的等待')],
    [('方法与请求体', '<p>301、302 的 POST 与 303 的非 GET/HEAD 请求会被改成 GET 并去掉请求体和相关头;307、308 保留方法与请求体。</p>'),
     ('跳转记录', '<p>最终响应的 <code>meta</code> 里有 <code>redirect_urls</code>、<code>redirect_reasons</code>、<code>redirect_times</code>、<code>redirect_ttl</code>;<code>response.url</code> 是最终地址,请求的 URL 可能还带着片段。</p>'),
     ('次数上限', '<p><code>REDIRECT_MAX_TIMES</code>(默认 20)用尽后丢弃请求并抛 <code>IgnoreRequest</code>,errback 能收到。</p>'),
     ('关闭跳转', '<p><code>dont_redirect</code> 或 <code>handle_httpstatus_list</code> 让回调直接拿到 3xx 响应。</p>'),
     ('请求头', '<p>跨主机跳转会删除 <code>Cookie</code> 和 <code>Authorization</code>;跳转请求优先级 +2,会插队。</p>'),
     ('Location 的各种写法', '<p>相对路径与协议相对地址会被补全;没有 <code>Location</code> 或目标不是 http(s) 时不跳转。</p>'),
     ('meta refresh', '<p>秒数小于 <code>METAREFRESH_MAXDELAY</code>(默认 100)的 meta refresh 会被立即跟随,不会等待那么多秒。</p>')],
    steps,
    [ENV_Y + '。服务器按路径返回各种 3xx、循环重定向(每次跳到新 URL)、meta refresh 页面,并记录每个请求的方法、请求体和头',
     '没有验证:HTTPS 跳到 HTTP 时 Cookie 与 Authorization 的处理(源码里有 https 例外分支);代理(_scheme_proxy)与重定向的组合;Referer 策略(REFERRER_POLICY)对重定向后 Referer 的影响;HEAD 请求的 meta refresh;重定向与 HTTP 缓存的组合'],
    '重定向')
